"use client";

import React from "react";
import { cn } from "@/lib/utils";

export interface TextMarqueeProps<T = string>
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "prefix" | "children"> {
  items: T[];
  renderItem?: (item: T, index: number) => React.ReactNode;
  prefix?: React.ReactNode;
  speed?: number;
  height?: number;
  itemHeight?: number;
  className?: string;
}

export function TextMarquee<T = string>({
  items,
  renderItem,
  prefix,
  className,
  style,
  speed = 1,
  height = 200,
  itemHeight = 40,
  ...props
}: TextMarqueeProps<T>) {
  const count = items.length;
  const safeSpeed = Math.max(speed, 0.01);
  const safeHeight = Math.max(height, 0);
  const safeItemHeight = Math.max(itemHeight, 1);

  if (count === 0) return null;

  // Duplicate items array for seamless 60fps infinite loop scrolling
  const displayItems = [...items, ...items, ...items];

  return (
    <div
      data-slot="text-marquee"
      className={cn("spell-text-marquee relative flex items-center select-none", className)}
      style={style}
      {...props}
    >
      <div className="spell-text-marquee__content relative flex h-min w-min flex-row items-center gap-2 overflow-hidden">
        {prefix && (
          <div className="spell-text-marquee__prefix relative size-auto whitespace-pre font-semibold text-zinc-900 dark:text-white">
            {prefix}
          </div>
        )}

        <div
          className="spell-text-marquee__viewport relative w-auto overflow-hidden opacity-100"
          style={{
            height: `${safeHeight}px`,
            maskImage: "linear-gradient(rgba(0, 0, 0, 0) 0%, rgb(0, 0, 0) 43.6902%, rgba(0, 0, 0, 0) 100%)",
            WebkitMaskImage: "linear-gradient(rgba(0, 0, 0, 0) 0%, rgb(0, 0, 0) 43.6902%, rgba(0, 0, 0, 0) 100%)",
          }}
        >
          <div
            className="spell-text-marquee__track relative h-full animate-spell-text-marquee-slide"
            style={{
              animationDuration: `${count * 2 / safeSpeed}s`,
            }}
          >
            {displayItems.map((item, index) => (
              <div
                key={`${index}-${String(item)}`}
                className="spell-text-marquee__item flex items-center font-bold text-blue-600 dark:text-blue-400"
                style={{
                  height: `${safeItemHeight}px`,
                }}
              >
                {renderItem ? renderItem(item, index % count) : String(item)}
              </div>
            ))}
          </div>
        </div>
      </div>

      <style jsx global>{`
        @keyframes spell-text-marquee-slide-vertical {
          0% {
            transform: translateY(0%);
          }
          100% {
            transform: translateY(-50%);
          }
        }
        .animate-spell-text-marquee-slide {
          animation: spell-text-marquee-slide-vertical linear infinite;
        }
        .animate-spell-text-marquee-slide:hover {
          animation-play-state: paused;
        }
      `}</style>
    </div>
  );
}

export default TextMarquee;
